#!/usr/bin/env python3
"""emit_playground.py — render each screen of the design/new React+Babel
playground to a chrome-stripped, self-contained static HTML surface at
design/new/surfaces/<surface>.html, for the freeze gate (freeze_design.sh check 5
loads surfaces/*.html headlessly and fails on any console/page error, so
emitted files are hermetic: no React/Babel/CDN, all CSS inlined, DOM frozen).

Usage:
  emit_playground.py [--app <app-root>]   emit (default app root: $APPBOX_APP)
  emit_playground.py --self-test          hermetic calibration (fixtures/)
  EMIT_RENDER=skip emit_playground.py     skip the browser pass entirely

Exit discipline (freeze_design.sh precedent): 0 = every emitted surface
rendered error-free · 1 = registry missing / render or extraction failure ·
2 = environment (no app root, no render backend). Gates never auto-install:
the render-backend cascade is `uv run --with playwright` -> system python3
with playwright importable -> exit 2 with install instructions.

Contract:
  - serve <app>/design/ on an ephemeral port; load new/index.html and read
    window.P2.registry (array of {id, shell, roles, surface, ...}; `surface` is
    a canonical ID or null). Missing registry -> exit 1.
  - per entry with surface != null: pick an allowed role (entry.roles[0],
    else the role whose shells contain entry.shell, from window.P2.roles), goto
    new/index.html?role=<role>&screen=<id>, settle ~1500ms, fail on any
    console/page error, extract the SCREEN CONTENT only: the .phone-screen
    subtree with every design/exclusions.json `selectors` match stripped.
  - compose a standalone doc (tokens.css + app.css inlined as <style>, asset
    URLs rewritten assets/... -> ../assets/...) and write
    design/new/surfaces/<surface>.html on diff only, with a timestamp-free
    GENERATED banner naming the source screen.
"""
import argparse
import functools
import http.server
import importlib.util
import json
import os
import re
import shutil
import socketserver
import subprocess
import sys
import tempfile
import threading
from pathlib import Path
from urllib.parse import quote

TOOL = Path(__file__).resolve()
FIXTURE_APP = TOOL.parent / "fixtures" / "app"

# The screen-content root inside the playground's iPhone frame: everything
# outside it (stage, toolbar, frame hardware) is chrome by construction;
# chrome INSIDE it (fake status bar, HUD overlays) is stripped via the
# exclusions.json selectors.
CONTENT_ROOT = ".phone-screen"

DOC = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<link rel="icon" href="data:,">
__BANNER__
<title>__SURFACE__</title>
<style>
__TOKENS__
</style>
<style>
__APPCSS__
</style>
</head>
<body>
__CONTENT__
</body>
</html>
"""

EXTRACT_JS = """(args) => {
  const root = document.querySelector(args.root);
  if (!root) return { ok: false, error: 'screen-content root not found: ' + args.root };
  const clone = root.cloneNode(true);
  for (const sel of args.selectors) {
    let hits;
    try { hits = clone.querySelectorAll(sel); }
    catch (e) { return { ok: false, error: 'bad exclusion selector ' + JSON.stringify(sel) + ' — ' + e }; }
    hits.forEach(n => n.remove());
  }
  return { ok: true, html: clone.outerHTML };
}"""


def banner(screen_id, role):
    return ("<!-- GENERATED by stacked_kit/tools/emit_playground — do not hand-edit. "
            f"Source: design/new/index.html screen '{screen_id}' (role '{role}'). -->")


def strip_css_comments(css):
    """CSS comments carry no styling; dropping them keeps freeze check-3 chrome
    signatures (e.g. 'tweak' inside a /* */ comment) out of emitted surfaces."""
    return re.sub(r"/\*.*?\*/", "", css, flags=re.S)


def role_for(entry, roles):
    """Allowed role: entry.roles[0], else the role whose shells contain the
    entry's shell. Liberal about window.P2.roles shape: {id: {shells: [...]}} or
    {id: [...]} or [{id, shells}]."""
    r = entry.get("roles")
    if isinstance(r, list) and r:
        return r[0]
    shell = entry.get("shell")
    pairs = []
    if isinstance(roles, dict):
        for rid, cfg in roles.items():
            shells = cfg.get("shells") if isinstance(cfg, dict) else cfg
            pairs.append((rid, shells if isinstance(shells, list) else []))
    elif isinstance(roles, list):
        for cfg in roles:
            if isinstance(cfg, dict):
                pairs.append((cfg.get("id"), cfg.get("shells") or []))
    for rid, shells in pairs:
        if shell in shells:
            return rid
    return pairs[0][0] if pairs else None


def emit(app, check=False):
    """The browser pass. Runs under whatever interpreter has playwright (the
    --worker re-exec target of the backend cascade). Returns 0/1.
    check=True renders everything but WRITES NOTHING — each rendered result is
    compared against the on-disk surface (the pre-gate drift guard)."""
    design = app / "design"
    new = design / "new"
    for req in (new / "index.html", new / "tokens.css", new / "app.css", new / "exclusions.json"):
        if not req.is_file():
            print(f"FAIL: missing {req.relative_to(app)} — the playground (new/index.html + tokens.css + app.css) "
                  "and exclusions.json must exist", file=sys.stderr)
            return 1
    try:
        selectors = json.loads((new / "exclusions.json").read_text()).get("selectors", [])
        if not isinstance(selectors, list):
            raise ValueError('"selectors" must be a list')
    except Exception as e:
        print(f"FAIL: design/new/exclusions.json does not parse — {e}", file=sys.stderr)
        return 1
    tokens = strip_css_comments((new / "tokens.css").read_text())
    appcss = strip_css_comments((new / "app.css").read_text())

    class Quiet(http.server.SimpleHTTPRequestHandler):
        def log_message(self, *a):
            pass

    srv = socketserver.ThreadingTCPServer(("127.0.0.1", 0), functools.partial(Quiet, directory=str(design)))
    port = srv.server_address[1]
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    try:
        from playwright.sync_api import sync_playwright
        failures = []
        drifted = []
        rendered = 0
        with sync_playwright() as pw:
            browser = pw.chromium.launch()

            def fresh_page():
                pg = browser.new_page(viewport={"width": 390, "height": 844})
                msgs = []
                pg.on("console", lambda m: msgs.append(m.text) if m.type == "error" else None)
                pg.on("pageerror", lambda e: msgs.append(str(e)))
                return pg, msgs

            base = f"http://127.0.0.1:{port}/new/index.html"
            pg, msgs = fresh_page()
            pg.goto(base)
            pg.wait_for_timeout(1500)
            registry = pg.evaluate("() => (window.P2 && window.P2.registry) || null")
            roles = pg.evaluate("() => (window.P2 && window.P2.roles) || null")
            pg.close()
            for m in msgs:
                failures.append(f"registry load: {m}")
            if registry is None:
                print("FAIL: window.P2.registry not found on design/new/index.html — the playground must expose "
                      "the screen registry (array of {id, shell, roles, surface, ...}) as window.P2.registry",
                      file=sys.stderr)
                return 1
            if not isinstance(registry, list):
                print("FAIL: window.P2.registry is not an array of screen entries", file=sys.stderr)
                return 1

            seen = {}
            for entry in registry:
                if not isinstance(entry, dict):
                    continue
                surface = entry.get("surface")
                if not surface:
                    continue  # registry-null screens are playground-only, never emitted
                sid = entry.get("id")
                if surface in seen:
                    failures.append(f"surface collision: '{surface}' claimed by both '{seen[surface]}' and '{sid}'")
                    continue
                seen[surface] = sid
                role = role_for(entry, roles)
                if not role:
                    failures.append(f"{surface}: no usable role for screen '{sid}' "
                                    "(entry.roles empty and no window.P2.roles shell match)")
                    continue
                pg, msgs = fresh_page()
                pg.goto(f"{base}?role={quote(str(role))}&screen={quote(str(sid))}")
                pg.wait_for_timeout(1500)
                res = pg.evaluate(EXTRACT_JS, {"root": CONTENT_ROOT, "selectors": selectors})
                pg.close()
                for m in msgs:
                    failures.append(f"{surface}: console/page error — {m}")
                if not res.get("ok"):
                    failures.append(f"{surface}: {res.get('error')}")
                    continue
                # surfaces/ lives INSIDE the producer folder (2026-07-25 reorg), so
                # assets/ is one level up. The pre-reorg rule (../new/assets/)
                # resolved to design/new/new/assets and 404'd every asset.
                content = re.sub(r'(src|href)="assets/', r'\1="../assets/', res["html"])
                doc = (DOC.replace("__BANNER__", banner(sid, role))
                          .replace("__SURFACE__", str(surface))
                          .replace("__TOKENS__", tokens)
                          .replace("__APPCSS__", appcss)
                          .replace("__CONTENT__", content))
                # Emitted surfaces live inside their own producer folder
                # (2026-07-25 reorg): design/new/surfaces/.
                out = new / "surfaces" / f"{surface}.html"
                if check:
                    if not out.exists():
                        drifted.append(f"{surface}.html")
                        print(f"DRIFT design/new/surfaces/{surface}.html (not on disk — run emit)")
                    elif out.read_text() != doc:
                        drifted.append(f"{surface}.html")
                        print(f"DRIFT design/new/surfaces/{surface}.html (playground changed — re-run emit)")
                    else:
                        print(f"in-sync design/new/surfaces/{surface}.html")
                else:
                    out.parent.mkdir(exist_ok=True)
                    if out.exists() and out.read_text() == doc:
                        print(f"unchanged design/new/surfaces/{surface}.html (write-on-diff: content identical)")
                    else:
                        out.write_text(doc)
                        print(f"wrote design/new/surfaces/{surface}.html  (screen '{sid}', role '{role}')")
                rendered += 1
            browser.close()
        orphans = []
        if check:
            sdir = new / "surfaces"
            if sdir.is_dir():
                for p in sorted(sdir.glob("*.html")):
                    if p.stem not in seen:
                        orphans.append(p.name)
                        print(f"  note: orphan surface {p.name} (no registry entry — left alone)")
        for f in failures:
            print(f"FAIL: render: {f}", file=sys.stderr)
        if drifted:
            print(f"FAIL: emit --check: {len(drifted)} surface(s) drifted (re-run emit): {', '.join(drifted)}",
                  file=sys.stderr)
        if failures or drifted:
            return 1
        if check:
            print(f"emit --check: PASS — {rendered} surface(s) in-sync, {len(orphans)} orphan(s) noted")
        else:
            print(f"emit: PASS — {rendered} surface(s) emitted to {new}/surfaces/")
        return 0
    finally:
        srv.shutdown()


def run_with_backend(app, check=False):
    """Backend cascade (freeze_design.sh precedent): uv -> system playwright -> exit 2."""
    extra = ["--check"] if check else []
    if shutil.which("uv"):
        return subprocess.call(["uv", "run", "--with", "playwright", "python",
                                str(TOOL), "--worker", "--app", str(app)] + extra)
    if importlib.util.find_spec("playwright"):
        return emit(app, check=check)
    print("emit: ERROR (exit 2) — no render backend. Install one of:", file=sys.stderr)
    print("  uv (https://docs.astral.sh/uv/)   — emit uses: uv run --with playwright", file=sys.stderr)
    print("  pip install playwright && python3 -m playwright install chromium", file=sys.stderr)
    print("(browsers already cached at ~/Library/Caches/ms-playwright are reused.)", file=sys.stderr)
    print("Hermetic runs: EMIT_RENDER=skip emit_playground.py ...", file=sys.stderr)
    return 2


def self_test():
    failed = []

    def chk(cond, label):
        print(("  ✓ " if cond else "  ✗ ") + label)
        if not cond:
            failed.append(label)

    def run(app, env=None, extra=None):
        e = dict(os.environ)
        e.pop("EMIT_RENDER", None)
        if env:
            e.update(env)
        return subprocess.run([sys.executable, str(TOOL), "--app", str(app)] + (extra or []),
                              capture_output=True, text=True, env=e)

    def skip_case(app):
        r = run(app, env={"EMIT_RENDER": "skip"})
        chk(r.returncode == 0 and "SKIPPED" in r.stdout,
            f"EMIT_RENDER=skip: exit 0 + skip note (rc={r.returncode})")
        chk(not list((app / "design" / "new").glob("surfaces/*.html")),
            "EMIT_RENDER=skip: no surfaces written")

    with tempfile.TemporaryDirectory() as td:
        app = Path(td) / "app"
        shutil.copytree(FIXTURE_APP, app)
        if os.environ.get("EMIT_RENDER") == "skip":
            skip_case(app)
            print("  (browser scenarios skipped — EMIT_RENDER=skip in ambient env)")
        else:
            r = run(app)
            chk(r.returncode == 0,
                f"fixture emit exits 0 (rc={r.returncode}: {(r.stdout + r.stderr).strip().splitlines()[-1:]})")
            surf = app / "design" / "new" / "surfaces"
            home = surf / "fixture_home_view.html"
            chk(home.is_file(), "surface emitted at design/new/surfaces/fixture_home_view.html")
            chk((surf / "fixture_studio_view.html").is_file(),
                "roles-less entry falls back to the role whose shells contain its shell (studio → leo)")
            files = sorted(p.name for p in surf.glob("*.html"))
            chk(files == ["fixture_home_view.html", "fixture_studio_view.html"],
                f"registry-null screen not emitted (files: {files})")
            if home.is_file():
                h = home.read_text()
                chk('class="t-hud"' not in h, "chrome stripped (fixture exclusions selector .t-hud gone)")
                chk("<script" not in h and "http://" not in h and "https://" not in h,
                    "hermetic: no script tags, no CDN/remote URLs")
                chk("../assets/icon.svg" in h, "asset URLs rewritten for surfaces/ (../assets/...)")
                # Non-vacuous: resolve every rewritten URL against the emitted
                # file. Asserting the string alone kept this green while the
                # pre-reorg rule 404'd in the freeze render pass.
                import re as _re
                _bad=[u for u in _re.findall(r'(?:src|href)="((?:\.\./)+[^"]+)"', h)
                      if not (home.parent / u).resolve().exists()]
                chk(not _bad, f"every rewritten asset URL resolves on disk (dangling: {_bad})")
                chk("GENERATED" in h and "do not hand-edit" in h and "train.home" in h,
                    "generated banner names source screen, timestamp-free")
                chk("--fixture-ink" in h and ".fixture-card" in h, "tokens.css + app.css inlined as <style>")
                chk("tweak" not in h, "CSS comments stripped (no 'tweak' from the tokens.css comment — freeze check-3)")
                chk("Fixture Home" in h, "screen DOM pre-rendered into the doc")
            r2 = run(app)
            chk(r2.returncode == 0 and "unchanged" in r2.stdout,
                "write-on-diff: an in-sync re-run reports unchanged")
            # --check drift guard: in-sync after a fresh emit
            rc1 = run(app, extra=["--check"])
            chk(rc1.returncode == 0 and "in-sync" in rc1.stdout,
                f"--check: in-sync after a fresh emit (rc={rc1.returncode})")
            # orphan: a surface with no registry entry is informational, not a failure
            (surf / "legacy_orphan_view.html").write_text("<html>legacy frozen surface</html>\n")
            rc2 = run(app, extra=["--check"])
            chk(rc2.returncode == 0 and "orphan" in rc2.stdout and "legacy_orphan_view.html" in rc2.stdout,
                "--check: orphan surface reported as info, not a failure")
            # hand-edit → DRIFT, exit 1
            if home.is_file():
                home.write_text(home.read_text() + "<!-- hand edit -->\n")
            rc3 = run(app, extra=["--check"])
            chk(rc3.returncode == 1 and "DRIFT" in (rc3.stdout + rc3.stderr)
                and "fixture_home_view.html" in (rc3.stdout + rc3.stderr),
                "--check: hand-modified surface reports DRIFT and exits 1")
            # planted drift: break the exclusion selector → chrome survives → detectable downstream
            ex = app / "design" / "new" / "exclusions.json"
            ex.write_text(ex.read_text().replace(".t-hud", ".t-hud-broken"))
            r3 = run(app)
            drift = home.read_text() if home.is_file() else ""
            chk(r3.returncode == 0 and 'class="t-hud"' in drift,
                "planted drift detectable: broken selector leaves chrome in the emitted file")
            # missing registry → exit 1 with a clear message
            idx = app / "design" / "new" / "index.html"
            idx.write_text(idx.read_text().replace("registry:", "registry_disabled:"))
            r4 = run(app)
            chk(r4.returncode == 1 and "window.P2.registry" in (r4.stdout + r4.stderr),
                "missing window.P2.registry exits 1 with a clear message")

    if failed:
        print(f"SELF-TEST FAILED ({len(failed)} check(s)):")
        for f in failed:
            print(f"  - {f}")
        sys.exit(1)
    print("ALL GREEN")


def main(argv):
    ap = argparse.ArgumentParser(description="emit chrome-stripped static surfaces from the design/new playground")
    ap.add_argument("--app", help="app root (default: $APPBOX_APP)")
    ap.add_argument("--check", action="store_true",
                    help="drift guard: render + compare against on-disk surfaces, write nothing")
    ap.add_argument("--self-test", action="store_true", help="hermetic calibration against fixtures/")
    ap.add_argument("--worker", action="store_true", help=argparse.SUPPRESS)  # cascade re-exec target
    args = ap.parse_args(argv)

    if args.self_test:
        self_test()
        return

    app = args.app or os.environ.get("APPBOX_APP")
    if not app:
        print("emit: ERROR (exit 2) — no app root: pass --app <app-root> or set $APPBOX_APP", file=sys.stderr)
        sys.exit(2)
    app = Path(app).resolve()
    if not app.is_dir():
        print(f"emit: ERROR (exit 2) — app root not found: {app}", file=sys.stderr)
        sys.exit(2)

    if os.environ.get("EMIT_RENDER") == "skip":
        print("  (emit SKIPPED — EMIT_RENDER=skip; no surfaces written — hermetic/CI runs only)")
        sys.exit(0)

    if args.worker:
        sys.exit(emit(app, check=args.check))
    sys.exit(run_with_backend(app, check=args.check))


if __name__ == "__main__":
    main(sys.argv[1:])
